    add(l,'punctuation','Оформить начало и конец','Исправь только регистр и знаки: i am ben',['I am Ben.'],'I и Ben с заглавной; в конце точка.')
    add(l,'identify','Узнать вопросительный знак','Какой знак обозначает прямой вопрос: . или ? Введи знак.',['?'],'Вопрос обозначается ?, утверждение обычно заканчивается точкой.')
    add(l,'reading','Понять место','По A0L05-R где Mia? Ответь по-русски или фрагментом по-английски.',['дома'],'At home — дома.',['at home'],phase='reading')
    add(l,'reading','Найти состояние','Выпиши из A0L05-R полное предложение о готовности.',['I am ready.'],'Ready означает готовность; calm — спокойствие.',phase='reading')
    add(l,'writing','Создать первое своё предложение','Представься от своего или вымышленного имени одним предложением с I am.',[],'Любое имя допустимо; это не сравнение с именем в образце.',criteria=['Одно полное утверждение I am + имя.','Имя и I с заглавной; точка в конце.','Нет лишнего двоеточия между I и am.'],sample='I am Ben.',phase='writing')
    add(l,'writing','Написать микропрофиль','Напиши три предложения: имя, место, состояние. Используй знакомый словарь, факты можно придумать.',[],'Для каждого пункта используй I am. Можно быть calm, ready, happy или tired; это не список обязательных характеристик.',criteria=['Три понятных предложения об одном говорящем.','Имя, место и состояние названы через I am.','Заглавные, пробелы и точки оформлены.'],sample='I am Ben. I am at home. I am happy.',phase='writing')
    add(l,'punctuation','Проверить границы','Перепиши как два утверждения: i am here i am ready',['I am here. I am ready.'],'Нужны две заглавные I и две точки.',phase='checkpoint')
    add(l,'correct','Повторить после перерыва','Сохрани I и смысл, исправь: i calm.',['I am calm.'],'I заглавное; после I нужна am; точка уже есть.',phase='delayed_review')
    out.append(l)
    return out
